text:
{
  "questions": [
    {
      "n": 1,
      "start": "Qu'en est-il globalement",
      "end": "du projet Imago?"
    },
    {
      "n": 2,
      "start": "Le Conseit d'Etat a-t-il avancé",
      "end": "dans la définition de ce que devrait être ou pas le futur centre de formation des métiers de la terre?"
    },
    {
      "n": 3,
      "start": "Qu'en est-il des sites choisis ou pressentis?",
      "end": "Des contacts récents ont-ils été pris avec les communes concernées?"
    },
    {
      "n": 4,
      "start": "Quels critères ont été définis",
      "end": "pour déterminer le choix dudit futur site?"
    },
    {
      "n": 5,
      "start": "Quel calendrier le Conseil d'Etat a-t-il fixé",
      "end": "pour la mise en œuvre de ce projet?"
    },
    {
      "n": 6,
      "start": "Plus généralement qu'en est-il de la vision stratégique",
      "end": "développée par le Conseil d'Etat en matière de regroupement des formations dans le domaine agri-viticole?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Le projet IMAGO est en cours",
      "end": "et avance selon différentes étapes inhérentes à un projet de cette envergure."
    },
    {
      "n": 2,
      "start": "Le 19 décembre 2018, dans sa réponse aux postulats Nicolet et Perrin,",
      "end": "le Conseil d’Etat a décidé d’orienter le projet sur une solution à deux sites ; l’un à Changins et l’autre sur un emplacement devant être déterminé par appel d’offre aux communes vaudoises."
    },
    {
      "n": 3,
      "start": "Comme mentionné ci-dessus, le Conseil d’Etat souhaite implanter une partie des activités IMAGO à Changins.",
      "end": "Des contacts formels seront établis suite aux réponses des communes à l’appel d’offre qui leur sera soumis."
    },
    {
      "n": 4,
      "start": "Comme mentionné précédemment, l’Etat de Vaud envisage de regrouper sur deux sites l’ensemble des prestations publiques en relation avec l’agriculture.",
      "end": "Par conséquent il ne s’agit plus de déterminer un futur site unique."
    },
    {
      "n": 5,
      "start": "Le projet est actuellement mis en œuvre. Des décisions d’orientation ont été prises",
      "end": "et le projet est entré dans la phase de définition des besoins des futurs occupants du site, ainsi que de ses caractéristiques."
    },
    {
      "n": 6,
      "start": "Le rapport final aux postulats Nicolet et Perrin, validés par le Conseil d’Etat le 19 décembre 2018 fait l’état des lieux",
      "end": "de la formation professionnelle agricole dans le canton de Vaud. Il montre que celle-ci a évolué au cours de ces dernières années."
    }
  ],
  "submitter": "Felix Stürner",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": {
    "start": "Introduction",
    "end": "offrant ainsi des perspectives intéressantes à cette branche."
  }
}
